{"path": "/app/shipclient/retry.py", "content": """"Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

# Defaults from the HTTP client standard (v3) and rate limit handling.
_DEFAULT_ATTEMPTS = 5
_DEFAULT_CAP = 8.0
_DEFAULT_MAX_RETRY_AFTER = 30.0

# Current retry profiles: service -> (attempts, backoff cap, max Retry-After).
_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_RETRYABLE_STATUSES = {429, 502, 503, 504}
_IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_UNSAFE_METHODS = {"POST", "PATCH"}

_MONTHS = {
    "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
    "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
}
_HTTP_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) "
    r"(\d{2}):(\d{2}):(\d{2}) GMT"
)
_INTEGER = re.compile(r"[0-9]+")


def _lower_headers(headers):
    return {str(k).strip().lower(): v for k, v in (headers or {}).items()}


def _parse_retry_after(value, now):
    """Wait in seconds from a Retry-After value, or None if malformed."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    if _INTEGER.fullmatch(value) and value.isascii():
        return float(int(value))
    m = _HTTP_DATE.fullmatch(value)
    if not m:
        return None
    _, day, mon, year, hh, mm, ss = m.groups()
    month = _MONTHS.get(mon)
    if month is None:
        return None
    try:
        when = datetime(int(year), month, int(day), int(hh), int(mm), int(ss),
                        tzinfo=timezone.utc)
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    req = _lower_headers(request_headers)
    resp = _lower_headers(response_headers)

    # Which failures are retried.
    if status is not None and status not in _RETRYABLE_STATUSES:
        return None

    # Which requests are retried.
    verb = (method or "").strip().upper()
    if verb in _IDEMPOTENT_METHODS:
        pass
    else:
        key = req.get("idempotency-key")
        if not (isinstance(key, str) and key.strip()):
            return None

    # Settings, possibly from the service's current retry profile.
    service = req.get("x-service")
    profile = None
    if isinstance(service, str):
        profile = _PROFILES.get(service.strip().lower())
    max_attempts, cap, max_retry_after = profile or (
        _DEFAULT_ATTEMPTS, _DEFAULT_CAP, _DEFAULT_MAX_RETRY_AFTER)

    if attempt >= max_attempts:
        return None

    delay = min(0.25 * (2 ** (attempt - 1)), cap)

    if status in (429, 503) and "retry-after" in resp:
        wait = _parse_retry_after(resp["retry-after"], now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(wait, delay)

    return float(delay)
